import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
.visible .entry tanh_kernel(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 size
)
{
    .reg .u64 %rd<12>;
    .reg .u32 %r<12>;
    .reg .f32 %f<12>;
    .reg .pred %p<4>;
    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.u32 %r1, [size];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mov.u32 %r4, %tid.x;
    mad.lo.s32 %r5, %r2, %r3, %r4;
    mul.lo.s32 %r6, %r5, 4;
    add.s32 %r7, %r6, 3;
    setp.lt.u32 %p1, %r7, %r1;
    @!%p1 bra TAIL_CHECK;
    mul.wide.u32 %rd3, %r6, 4;
    add.s64 %rd4, %rd1, %rd3;
    add.s64 %rd5, %rd2, %rd3;
    ld.global.v4.f32 {%f1, %f2, %f3, %f4}, [%rd4];
    tanh.approx.f32 %f5, %f1;
    tanh.approx.f32 %f6, %f2;
    tanh.approx.f32 %f7, %f3;
    tanh.approx.f32 %f8, %f4;
    st.global.v4.f32 [%rd5], {%f5, %f6, %f7, %f8};
    bra DONE;
TAIL_CHECK:
    setp.ge.u32 %p2, %r6, %r1;
    @%p2 bra DONE;
    mov.u32 %r8, %r6;
TAIL_LOOP:
    setp.ge.u32 %p3, %r8, %r1;
    @%p3 bra DONE;
    mul.wide.u32 %rd6, %r8, 4;
    add.s64 %rd7, %rd1, %rd6;
    add.s64 %rd8, %rd2, %rd6;
    ld.global.f32 %f9, [%rd7];
    tanh.approx.f32 %f10, %f9;
    st.global.f32 [%rd8], %f10;
    add.s32 %r8, %r8, 1;
    bra TAIL_LOOP;
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("tanh_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input tensor must be on CUDA device"
        x_contig = x.contiguous()
        out = torch.empty_like(x_contig)

        total_elements = x_contig.numel()

        module = _get_ptx_module()

        block_x = 256
        vec_elements = (total_elements + 3) // 4
        grid_x = (vec_elements + block_x - 1) // block_x

        module.launch(
            "tanh_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x_contig, out, i32(total_elements)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )

        return out.view(x.shape)

